    return cmd
}

func run(cmd *cobra.Command, args []string) (string, error) {
    buf := new(bytes.Buffer)
    cmd.SetOut(buf)
    cmd.SetArgs(args)
    err := cmd.Execute()
    return buf.String(), err
}

func main() {
}

cases := []struct {
    args []string
    want string
}{
    {[]string{"--name", "Ana"}, "hello Ana\n"},
    {[]string{}, "hello world\n"},
}

for _, tc := range cases {
    out, _ := run(newGreetCmd(), tc.args)
    if out == tc.want {
        fmt.Println("PASS")
    } else {
        fmt.Printf("FAIL %q\n", out)
    }
}

